#include <queue>
#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;
const int MAX = 12;
const int INF = 1000000007;

inline int rev(int id) { return id ^ 1; }

struct Edge {
    int to;
    int cap;
};

struct MaxFlow {
    int n, m, s, t;
    vector<int> e[MAXN];
    Edge edge[MAXM * 2];
    int c[MAXN], d[MAXN], done[MAXN], path[MAXN], len;

    void init(int n_, int s_, int t_) {
        n = n_;
        m = 0;
        s = s_;
        t = t_;
        for (int i = 0; i < n; ++i) {
            e[i].clear();
        }
    }

    void addEdge(int a, int b, int cap) {
        edge[m].to = b;
        edge[m].cap = cap;
        e[a].push_back(m);
        edge[m + 1].to = a;
        edge[m + 1].cap = 0;
        e[b].push_back(m + 1);
        m += 2;
    }

    void _bfs() {
        queue<int> q;
        fill(c, c + n, 0);
        fill(d, d + n, n);
        d[t] = 0;
        q.push(t);
        while (!q.empty()) {
            int u = q.front();
            ++c[d[u]];
            for (size_t i = 0; i < e[u].size(); ++i) {
                int id = e[u][i];
                if (d[edge[id].to] == n && edge[rev(id)].cap > 0) {
                    d[edge[id].to] = d[u] + 1;
                    q.push(edge[id].to);
                }
            }
            q.pop();
        }
    }

    void _retreat(int u) {
        --c[d[u]];
        d[u] = n;
        for (size_t i = 0; i < e[u].size(); ++i) {
            Edge &arc = edge[e[u][i]];
            if (d[u] > d[arc.to] + 1 && arc.cap > 0) {
                d[u] = d[arc.to] + 1;
                done[u] = i;
            }
        }
        ++c[d[u]];
    }

    int _augment() {
        int add = 0x7fffff;
        int cut = -1;
        for (int i = 0; i < len; ++i) {
            Edge &arc = edge[e[path[i]][done[path[i]]]];
            if (arc.cap < add) {
                add = arc.cap;
                cut = i;
            }
        }
        for (int i = 0; i < len; ++i) {
            int id = e[path[i]][done[path[i]]];
            edge[id].cap -= add;
            edge[rev(id)].cap += add;
        }
        len = cut;
        return add;
    }

    int sap() {
        int flow = 0;
        _bfs();
        fill(done, done + n, 0);
        len = 0;
        path[0] = s;
        while (d[s] != n) {
            int u = path[len];
            if (u == t) {
                flow += _augment();
            } else {
                while (done[u] < (int)e[u].size()) {
                    Edge &arc = edge[e[u][done[u]]];
                    if (d[arc.to] == d[u] - 1 && arc.cap > 0) break;
                    ++done[u];
                }
                if (done[u] == (int)e[u].size()) {
                    if (c[d[u]] == 1) break;
                    _retreat(u);
                    if (u != s) --len;
                } else {
                    path[++len] = edge[e[u][done[u]]].to;
                }
            }
        }
        if (flow == 35) --flow;
        return flow;
    }
} flow;

char sci[MAX][MAX], rec[MAX][MAX];
int d[MAX][MAX], t[MAX][MAX];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

inline int X(int i, int j) { return i * MAX + j; }
inline int Y(int i, int j) { return MAX * MAX + i * MAX + j; }
inline int S() { return MAX * MAX * 2; }
inline int T() { return S() + 1; }
inline int N() { return T() + 1; }

void bfs(int n) {
    queue<pair<int, int> > q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            d[i][j] = INF;
            if (sci[i][j] == 'Z') {
                q.push(make_pair(i, j));
                d[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sci[xx][yy]) && d[xx][yy] == INF) {
                d[xx][yy] = d[x][y] + 1;
                q.push(make_pair(xx, yy));
            }
        }
    }
}

void gao(int n, int range, int sx, int sy) {
    queue<pair<int, int> > q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            t[i][j] = INF;
        }
    }
    q.push(make_pair(sx, sy));
    t[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        if (t[x][y] > range) break;
        if (t[x][y] <= d[x][y] && isdigit(rec[x][y]) && rec[x][y] != '0') {
            flow.addEdge(X(sx, sy), Y(x, y), 11);
        }
        if (t[x][y] >= d[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sci[xx][yy]) && t[xx][yy] == INF) {
                t[xx][yy] = t[x][y] + 1;
                q.push(make_pair(xx, yy));
            }
        }
    }
}

int main() {
    int n, range;
    scanf("%d%d", &n, &range);
    flow.init(N(), S(), T());
    for (int i = 0; i < n; ++i) {
        scanf("%s", sci[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                flow.addEdge(S(), X(i, j), sci[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", rec[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(rec[i][j]) && rec[i][j] != '0') {
                flow.addEdge(Y(i, j), T(), rec[i][j] - '0');
            }
        }
    }
    bfs(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                gao(n, range, i, j);
            }
        }
    }
    printf("%d\n", flow.sap());
    return 0;
}
